const { funcao, argumentos = {} } = $json;
let metodo = 'POST', path = '', body = {};

if (funcao === 'processar_pedido') {
  const acao = argumentos.acao;
  if (acao === 'criar_venda') {
    metodo = 'POST';
    path = '/api/resource/Sales Order';
    body = { items: (argumentos.itens || []).map(i => ({
      item_code: i.produto_id, qty: i.quantidade, rate: i.preco_unitario
    })) };
  } else if (acao === 'confirmar') {
    if (!argumentos.id_pedido) throw new Error('id_pedido é obrigatório para confirmar');
    metodo = 'PUT';
    path = `/api/resource/Sales Order/${encodeURIComponent(argumentos.id_pedido)}`;
    body = { status: 'To Deliver and Bill' };
  } else if (acao === 'cancelar' || acao === 'estornar') {
    // Não é um PUT simples — cancelamento de pedido no Brasil tem regra
    // fiscal (janela de 24h da NF-e) e efeito colateral de estoque/
    // pagamento. Isso é resolvido no branch dedicado logo abaixo, não
    // aqui — só valida o que é obrigatório e segue.
    if (!argumentos.id_pedido) throw new Error('id_pedido é obrigatório para ' + acao);
    if (!argumentos.motivo) throw new Error('motivo é obrigatório para ' + acao + ' (auditoria)');
  } else {
    throw new Error('acao inválida para processar_pedido: ' + acao);
  }
} else if (funcao === 'faturamento_expedicao') {
  if (!argumentos.id_pedido) throw new Error('id_pedido é obrigatório para faturamento_expedicao');
  metodo = 'POST';
  path = '/api/method/erpnext.selling.doctype.sales_order.sales_order.make_sales_invoice';
  body = { source_name: argumentos.id_pedido };
} else {
  throw new Error('Função desconhecida: ' + funcao);
}

return [{ json: { funcao, acao: argumentos.acao, id_pedido: argumentos.id_pedido, motivo: argumentos.motivo, metodo, path, body, conversa_id: $json.conversa_id, tenant_id: $json.tenant_id } }];

const input = $input.first().json;
const meta = $node['Prepara Ação de Alto Impacto'].json;

const sucesso = !input.error;
const dados = input.data !== undefined ? input.data : (input.message !== undefined ? input.message : (input.error ? null : input));

return [{
  json: {
    conversa_id: meta.conversa_id,
    tenant_id: meta.tenant_id,
    funcao: meta.funcao,
    sucesso,
    dados,
    erro: input.error || null,
    aviso: (sucesso && meta.funcao === 'faturamento_expedicao')
      ? 'Fatura gerada como rascunho — submissão final (emissão de NF-e) exige confirmação separada, ainda não automatizada.'
      : null
  }
}];

const meta = $node['Prepara Ação de Alto Impacto'].json;
const resp = $input.first().json;
if (resp.error || !resp.data) {
  throw new Error('Não foi possível localizar o pedido ' + meta.id_pedido + ' para ' + meta.acao);
}
const invoice = resp.data;

// custom_nfe_autorizada_em: campo do app de localização brasileira do Ritmo
// que guarda o instante em que a NF-e foi autorizada pela SEFAZ. Ajustar o
// nome exato conforme o app fiscal realmente instalado (não confirmado).
const autorizadaEm = invoice.custom_nfe_autorizada_em ? new Date(invoice.custom_nfe_autorizada_em) : null;
const horasDesdeAutorizacao = autorizadaEm ? (Date.now() - autorizadaEm.getTime()) / 3600000 : null;
const dentro24h = autorizadaEm !== null && horasDesdeAutorizacao < 24;

const itensEspelhados = (invoice.items || []).map(i => ({
  item_code: i.item_code, qty: -Math.abs(i.qty), rate: i.rate
}));

return [{
  json: {
    ...meta,
    invoiceName: invoice.name,
    dentro24h,
    itensEspelhados,
    infinitepayReferencia: invoice.custom_infinitepay_transaction_nsu || null
  }
}];

const meta = $node['Decide Janela de 24h da NF-e'].json;
const resultado = $input.first().json;

const sucesso = !resultado.error;
const tipo = meta.dentro24h ? 'cancelamento_nfe' : 'nota_devolucao';

return [{
  json: {
    conversa_id: meta.conversa_id,
    tenant_id: meta.tenant_id,
    funcao: 'processar_pedido',
    sucesso,
    dados: sucesso ? { tipo, id_pedido: meta.invoiceName } : null,
    erro: sucesso ? null : (resultado.error || 'Falha ao processar ' + meta.acao),
    aviso: tipo === 'nota_devolucao'
      ? 'Fora da janela de 24h da NF-e — foi emitida nota de devolução em vez de cancelamento.'
      : null
  }
}];

// INTEGRAÇÃO PENDENTE DE CONFIRMAÇÃO — proposital.
// Não existe endpoint real confirmado pra isso ainda, e um palpite
// aqui poderia rodar em produção sem ninguém perceber que é chute.
// Por isso este nó não faz chamada nenhuma — só encerra o caminho
// com um erro claro. Quando a integração for confirmada, troque
// ESTE nó por um HTTP Request real apontando pro endpoint certo;
// o resto do workflow (busca de fatura, janela de 24h, criação da
// devolução, cancelamento da fatura, busca de credencial) já está
// pronto e não muda.
const meta = $node['Decide Janela de 24h da NF-e'].json;
return [{
  json: {
    conversa_id: meta.conversa_id,
    tenant_id: meta.tenant_id,
    funcao: 'processar_pedido',
    sucesso: false,
    dados: null,
    erro: 'Integração pendente: endpoint de cancelamento de NF-e do Ritmo ainda não confirmado (depende de qual app fiscal está instalado)',
    etapa_pendente: 'cancelamento_nfe'
  }
}];

